package sh.locus.goandroid;

import android.app.Activity;
import android.os.Bundle;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ProgressBar;
import android.widget.Spinner;
import android.widget.TextView;

import org.json.JSONArray;
import org.json.JSONObject;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

// These three classes are generated by `gomobile bind` from the Go package
// github.com/aniketv/gocore/mobile. There is no hand-written JNI anywhere.
import sh.locus.gocore.mobile.Greeter;
import sh.locus.gocore.mobile.Mobile;
import sh.locus.gocore.mobile.ProgressListener;

public class MainActivity extends Activity {

    // Constructing this loads libgojni.so and starts the Go runtime. It stays
    // loaded for the life of the process — you cannot unload it.
    private final Greeter greeter = Mobile.newGreeter();

    private TextView output;
    private ProgressBar progress;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        output = findViewById(R.id.outputText);
        progress = findViewById(R.id.progressBar);
        final EditText nameInput = findViewById(R.id.nameInput);
        final Spinner langSpinner = findViewById(R.id.langSpinner);

        // Cheapest possible proof the bridge works: a no-arg Go call.
        ((TextView) findViewById(R.id.versionText)).setText(Mobile.version());

        // Go handed us "de,en,fr,hi,ja" because []string cannot cross the
        // boundary. The trailing "xx" is not a real language — it is here to
        // exercise the error path.
        final List<String> languages = new ArrayList<>(Arrays.asList(greeter.languages().split(",")));
        languages.add("xx (invalid)");

        langSpinner.setAdapter(new ArrayAdapter<>(
                this,
                android.R.layout.simple_spinner_dropdown_item,
                languages));

        ((Button) findViewById(R.id.greetButton)).setOnClickListener(v ->
                greet(nameInput.getText().toString(),
                        languages.get(langSpinner.getSelectedItemPosition())));

        ((Button) findViewById(R.id.greetAllButton)).setOnClickListener(v ->
                greetAll(nameInput.getText().toString()));
    }

    /**
     * A synchronous call across JNI.
     *
     * <p>{@code greetJSON} is declared in Go as {@code ([]byte, error)}, so here it
     * returns a byte[] and throws on failure — an empty name or an unknown
     * language code lands in the catch block with the message Go's error carried.
     */
    private void greet(String name, String lang) {
        progress.setProgress(0);
        try {
            byte[] json = greeter.greetJSON(name, languageCode(lang));
            JSONObject greeting = new JSONObject(new String(json, StandardCharsets.UTF_8));

            output.setText("message  : " + greeting.getString("message") + "\n"
                    + "language : " + greeting.getString("language") + "\n"
                    + "at       : " + greeting.getString("at") + "\n\n"
                    + "raw JSON from Go (" + json.length + " bytes):\n"
                    + greeting.toString(2));
        } catch (Exception e) {
            // This is a Go error surfacing as a Java exception. JSONException is
            // caught by the same block — in Java it is checked, so it has to be.
            output.setText("Go returned an error:\n\n" + e.getMessage());
        }
    }

    /**
     * The reverse direction: Go calls back into Java.
     *
     * <p>Every callback arrives on a Go goroutine's thread, NOT the main thread,
     * so each one hops back via runOnUiThread before touching a view. Skipping
     * that is the single most common way to crash a gomobile app.
     */
    private void greetAll(String name) {
        progress.setProgress(0);
        output.setText("working…");

        greeter.greetAllAsync(name, new ProgressListener() {
            @Override
            public void onProgress(int percent) {
                runOnUiThread(() -> progress.setProgress(percent));
            }

            @Override
            public void onComplete(String resultJSON) {
                runOnUiThread(() -> renderAll(resultJSON));
            }

            @Override
            public void onError(String message) {
                runOnUiThread(() -> {
                    progress.setProgress(0);
                    output.setText("Go reported an error:\n\n" + message);
                });
            }
        });
    }

    private void renderAll(String resultJSON) {
        try {
            JSONArray arr = new JSONArray(resultJSON);
            StringBuilder sb = new StringBuilder()
                    .append(arr.length()).append(" greetings from Go:\n\n");

            for (int i = 0; i < arr.length(); i++) {
                JSONObject g = arr.getJSONObject(i);
                sb.append("  [").append(g.getString("language")).append("] ")
                        .append(g.getString("message")).append('\n');
            }
            output.setText(sb.toString());
        } catch (Exception e) {
            output.setText("Could not parse Go's response:\n\n" + e.getMessage());
        }
    }

    /** Trims the spinner's "xx (invalid)" entry down to a bare language code. */
    private static String languageCode(String label) {
        return label.length() > 2 ? label.substring(0, 2) : label;
    }
}
